namespace RonSijm.FluidHumidifier.Factories.Redshift;

public class RedshiftIdcApplicationFactory(string resourceName = null, Action<Humidifier.Redshift.RedshiftIdcApplication> factoryAction = null) : ResourceFactory<Humidifier.Redshift.RedshiftIdcApplication>(resourceName)
{

    internal List<InnerRedshiftIdcApplicationAuthorizedTokenIssuerFactory> AuthorizedTokenIssuerListFactories { get; set; } = [];

    internal List<InnerRedshiftIdcApplicationServiceIntegrationsUnionFactory> ServiceIntegrationsFactories { get; set; } = [];

    protected override Humidifier.Redshift.RedshiftIdcApplication Create()
    {
        var redshiftIdcApplicationResult = CreateRedshiftIdcApplication();
        factoryAction?.Invoke(redshiftIdcApplicationResult);

        return redshiftIdcApplicationResult;
    }

    private Humidifier.Redshift.RedshiftIdcApplication CreateRedshiftIdcApplication()
    {
        var redshiftIdcApplicationResult = new Humidifier.Redshift.RedshiftIdcApplication
        {
            GivenName = InputResourceName,
        };

        return redshiftIdcApplicationResult;
    }
    public override void CreateChildren(Humidifier.Redshift.RedshiftIdcApplication result)
    {
        base.CreateChildren(result);

        result.AuthorizedTokenIssuerList = AuthorizedTokenIssuerListFactories.Any() ? AuthorizedTokenIssuerListFactories.Select(x => x.Build()).ToList() : null;
        result.ServiceIntegrations = ServiceIntegrationsFactories.Any() ? ServiceIntegrationsFactories.Select(x => x.Build()).ToList() : null;
    }

} // End Of Class

